function() {
  var ip;
  try {
    var xhr = new XMLHttpRequest();
    xhr.open("GET", "https://api.ipify.org?format=json", false); // synchronous request
    xhr.send(null);
    if (xhr.status === 200) {
      ip = JSON.parse(xhr.responseText).ip;
    }
  } catch(e) {
    return "unknown";
  }

  // Match your office IPs
  if (ip === "87.121.23.124" || ip === "87.121.23.122") {
    return "internal";
  }
  return "external";
}

function () {
  var params = new URLSearchParams(window.location.search || "");
  return params.get("cludoquery") || params.get("query") || params.get("q") || "";
}

function () {
  // Look for rows in the cart table
  var rows = document.querySelectorAll('main#main-content table tbody tr');
  var items = [];
  rows.forEach(function (row) {
    try {
      // 1st cell: SKU + name
      var firstTd = row.querySelector('td:nth-child(1)');
      var skuP = firstTd ? firstTd.querySelector('p:nth-of-type(1)') : null;
      var nameP = firstTd ? firstTd.querySelector('p:nth-of-type(2)') : null;

      var skuText = skuP ? skuP.textContent.trim() : '';
      // Extract after "Vörunúmer:"  → e.g. "Vörunúmer: 135610_STK"
      var skuMatch = skuText.match(/Vörunúmer:\s*(.+)$/i);
      var item_id = skuMatch ? skuMatch[1].trim() : '';

      var item_name = nameP ? nameP.textContent.trim() : '';

      // 2nd cell: quantity
      var qtyTd = row.querySelector('td:nth-child(2)');
      var qtyText = qtyTd ? qtyTd.textContent : '1';
      var quantity = parseInt((qtyText+'').replace(/[^\d]/g, ''), 10);
      if (!quantity || isNaN(quantity)) quantity = 1;

      // 3rd cell: price (e.g. "994 kr. án/vsk")
      var priceTd = row.querySelector('td:nth-child(3)');
      var priceText = priceTd ? priceTd.textContent : '0';
      // keep digits only (ISK), remove thousand separators & currency
      var priceNum = parseInt((priceText+'').replace(/[^\d]/g, ''), 10);
      if (!priceNum || isNaN(priceNum)) priceNum = 0;

      items.push({
        item_id: item_id,
        item_name: item_name,
        quantity: quantity,
        price: priceNum,      // ISK as an integer
        currency: 'ISK'
      });
    } catch(e) {}
  });
  return items;
}

function () {
  var items = {{JS – cart_items}} || [];
  var total = 0;
  items.forEach(function (it) {
    var q = it.quantity || 1;
    var p = it.price || 0;
    total += q * p;
  });
  return total; // ISK
}

function () {
  var p = {{Page Path}} || location.pathname || "";
  var m = p.match(/\/minar-sidur\/vefpantanir\/(\d+)/);
  return m ? m[1] : "";
}

function () {
  // Look for "Samtals m/vsk" and return the number text in the <span>
  var ps = document.querySelectorAll('div[data-slot="card-content"] p');
  for (var i = 0; i < ps.length; i++) {
    var p = ps[i];
    if (/Samtals\s*m\/vsk/i.test(p.textContent || '')) {
      var span = p.querySelector('span');
      return span ? span.textContent.trim() : '';
    }
  }
  return '';
}

function () {
  var t = {{JS – order_total_raw}} || '';
  t = (t+'').replace(/[^\d.,-]/g,'').replace(/\s+/g,'');
  if (t.indexOf(',') > -1 && t.indexOf('.') === -1) t = t.replace(',', '.');
  t = t.replace(/(\d)[,.](?=\d{3}(\D|$))/g, '$1');
  var n = parseFloat(t);
  return isNaN(n) ? 0 : n;
}

function () {
  // Try the same table layout you have on /afgreida
  var rows = document.querySelectorAll(
    'main#main-content table tbody tr,' +                          // generic table
    'div[data-slot="card-content"] table tbody tr'                 // inside summary cards
  );

  var items = [];

  if (rows && rows.length) {
    rows.forEach(function (row) {
      try {
        // 1) First cell → SKU + Name
        var firstTd = row.querySelector('td:nth-child(1)');
        var skuP = firstTd ? firstTd.querySelector('p:nth-of-type(1)') : null;
        var nameP = firstTd ? firstTd.querySelector('p:nth-of-type(2)') : null;

        var skuText = skuP ? skuP.textContent.trim() : '';
        // Ex: "Vörunúmer: 135610_STK"
        var skuMatch = skuText.match(/Vörunúmer:\s*(.+)$/i);
        var item_id = skuMatch ? skuMatch[1].trim() : '';

        var item_name = nameP ? nameP.textContent.trim() : '';

        // 2) Second cell → quantity
        var qtyTd = row.querySelector('td:nth-child(2)');
        var qtyText = qtyTd ? qtyTd.textContent : '1';
        var quantity = parseInt((qtyText+'').replace(/[^\d]/g, ''), 10);
        if (!quantity || isNaN(quantity)) quantity = 1;

        // 3) Third cell → price (e.g., "994 kr. án/vsk")
        var priceTd = row.querySelector('td:nth-child(3)');
        var priceText = priceTd ? priceTd.textContent : '0';
        var priceNum = parseInt((priceText+'').replace(/[^\d]/g, ''), 10);
        if (!priceNum || isNaN(priceNum)) priceNum = 0;

        // push item
        if (item_id || item_name) {
          items.push({
            item_id: item_id,
            item_name: item_name,
            quantity: quantity,
            price: priceNum,
            currency: 'ISK'
          });
        }
      } catch (e) {}
    });

    if (items.length) return items;
  }

  // --- Fallback: look for any "Vörunúmer:" blocks if the success page is not a table ---
  var skuNodes = Array.prototype.slice.call(
    document.querySelectorAll('main#main-content p, main#main-content li, main#main-content div')
  ).filter(function (el) {
    return /Vörunúmer:/i.test(el.textContent || '');
  });

  skuNodes.forEach(function (node) {
    try {
      var skuMatch = (node.textContent || '').match(/Vörunúmer:\s*(.+)$/i);
      var item_id = skuMatch ? skuMatch[1].trim() : '';

      // Try to find the name near the SKU element
      var nameNode = node.parentElement && node.parentElement.querySelector('p:nth-of-type(2)');
      var item_name = nameNode ? nameNode.textContent.trim() : '';

      // naive qty/price near-by (adjust if needed)
      var quantity = 1;
      var priceNum = 0;
      var maybeQty = node.closest('tr,div,li') && node.closest('tr,div,li').querySelector('td:nth-child(2), .qty, [data-qty]');
      if (maybeQty) {
        var qt = (maybeQty.textContent || '').replace(/[^\d]/g, '');
        if (qt) quantity = parseInt(qt, 10) || 1;
      }
      var maybePrice = node.closest('tr,div,li') && node.closest('tr,div,li').querySelector('td:nth-child(3), .price, [data-price]');
      if (maybePrice) {
        var pt = (maybePrice.textContent || '').replace(/[^\d]/g, '');
        if (pt) priceNum = parseInt(pt, 10) || 0;
      }

      if (item_id || item_name) {
        items.push({
          item_id: item_id,
          item_name: item_name,
          quantity: quantity,
          price: priceNum,
          currency: 'ISK'
        });
      }
    } catch (e) {}
  });

  return items;
}

