function() {
  try {
    var n = document.querySelectorAll('script[type="application/ld+json"]');
    var data = null;
    for (var i=0;i<n.length;i++){
      var j = JSON.parse(n[i].textContent || '{}');
      if (Array.isArray(j)) {
        for (var k=0;k<j.length;k++){
          if (j[k] && (j[k]['@type']==='Product' || String(j[k]['@type']).indexOf('Product')>-1)) { data = j[k]; break; }
        }
      } else if (j && (j['@type']==='Product' || String(j['@type']).indexOf('Product')>-1)) { data = j; }
      if (data) break;
    }
    if (!data) return;
    var offers = data.offers || {};
    var price = Number(offers.price || (offers.priceSpecification && offers.priceSpecification.price)) || undefined;
    return {
      item_id: data.sku || data.mpn || data.productID || data.identifier || data.name,
      item_name: data.name,
      item_brand: (data.brand && (data.brand.name || data.brand)) || undefined,
      item_category: (data.category && (data.category.name || data.category)) || undefined,
      price: price,
      quantity: 1,
      currency: offers.priceCurrency || 'ISK'
    };
  } catch(e){ return; }
}

function(){
  var it = {{CJS – Product → GA4 item}};
  return it ? [it] : undefined;
}

function(){
  var a = {{CJS – ATC item}}; if(!a || !a.length) return;
  var i = a[0]; return (Number(i.price)||0) * (Number(i.quantity)||1);
}

function () {
  try {
    // Collect blocks (convert NodeList to Array)
    var nodes = document.querySelectorAll('script[type="application/ld+json"]');
    var blocks = [];
    for (var i = 0; i < nodes.length; i++) { blocks.push(nodes[i]); }

    // Helpers as function expressions (ES5)
    var safeParse = function (txt) {
      try { return JSON.parse(txt); } catch (e) { return null; }
    };

    var findProduct = function (obj) {
      if (!obj) return null;
      var arr;
      if (Object.prototype.toString.call(obj) === '[object Array]') {
        arr = obj;
      } else if (obj['@graph']) {
        arr = obj['@graph'];
      } else {
        arr = [obj];
      }
      for (var j = 0; j < arr.length; j++) {
        var n = arr[j]; if (!n) continue;
        var t = n['@type']; if (!t) continue;
        if (t === 'Product' || String(t).indexOf('Product') > -1) return n;
      }
      return null;
    };

    for (var b = 0; b < blocks.length; b++) {
      var text = blocks[b].textContent || blocks[b].innerText || '';
      var parsed = safeParse(text);
      var p = findProduct(parsed);
      if (p) return p;
    }
  } catch (e) {}
  return undefined;
}

function(){
  var toNum = function(x){
    if (!x) return undefined;
    // Remove spaces, "kr", "án/vsk", dots as thousand sep, keep decimals
    var s = String(x)
      .replace(/\./g,'')        // remove dots (thousand separators)
      .replace(/,/g,'.')        // swap comma for decimal
      .replace(/[^\d.]/g,'');   // strip non-numeric
    var n = Number(s);
    return isNaN(n) ? undefined : n;
  };

  // 1) Target your "Mitt verð" element
  var el = document.querySelector('p.ml-auto.text-\\[1\\.25rem\\].font-bold');
  if (el) return toNum(el.textContent);

  // 2) Fallback: any element containing "Mitt verð"
  var els = document.querySelectorAll('p');
  for (var i=0; i<els.length; i++){
    if (els[i].textContent.indexOf('Mitt verð')>-1){
      return toNum(els[i].textContent);
    }
  }

  return undefined;
}

function(){
  var p = {{CJS – Product JSONLD Object}};
  if (!p) return;

  var brand = (p.brand && (p.brand.name || p.brand)) || undefined;

  var offers = p.offers;
  if (Object.prototype.toString.call(offers) === '[object Array]') { offers = offers[0] || {}; }
  offers = offers || {};

  var toNumber = function(v){
    if (v == null) return undefined;
    if (typeof v === 'number') return v;
    var s = String(v).replace(/\s/g,'').replace(',', '.');
    var n = Number(s);
    return isNaN(n) ? undefined : n;
  };

  var price = toNumber(offers.price);
  if (price == null) price = {{CJS – DOM Price (fallback)}};

  return {
    item_id: p.sku || p.mpn || p.productID || p.identifier || p.name,
    item_name: p.name,
    item_brand: brand,
    price: price,
    quantity: 1,
    currency: offers.priceCurrency || 'ISK'
  };
}

function(){
  var it = {{CJS – Product → GA4 item}};
  return it ? [it] : undefined;
}

function(){
  var it = {{CJS – Product → GA4 item}};
  return it && it.price ? it.price : undefined;
}

function(){
  var x = {{JS – purchase_items}};
  return x && Object.prototype.toString.call(x) === '[object Array]' && x.length > 0;
}

function() {
  try {
    var id = {{JS – order_id_from_path}} + '';
    if (!id) return false;

    var key = 'ga4_seen_txn_' + id;

    // les bara - skrifar ekki
    if (sessionStorage.getItem(key)) {
      return true;  // duplicate
    }

    return false;  // not a duplicate
  } catch(e) {
    return false;
  }
}

